    synopsis: "Em novembro de 2022, o Sesc Mogi das Cruzes realizou a segunda edição do projeto Quintais Negros, que trouxe reflexões sobre os processos de urbanização da Vila Industrial, um dos mais conhecidos e queridos bairros da cidade. Neste documentário, que registrou toda a ação, é possível descobrir como essas pessoas chegaram de outros estados, em sua maioria negras, e como são as dinâmicas sociais que ocorrem nos dias atuais, influenciadas pela cultura afrodescendente, por meio de manifestações culturais, artísticas e religiosas.",
    directorNote: "Narrativa documental que costura caminhada noturna pelas ruas do bairro, rodas de diálogo no Sesc Mogi, Paróquia Nossa Senhora do Rosário, Estádio Nogueirão e o barracão da G.R.E.S. Unidos da Vila Industrial, alternando voos de drone ao entardecer com retratos em teleobjetiva 135mm e grande-angular na mão.",
